Fixpoint wspan (s : list Z) : nat :=
  match s with
  | c :: s' => if is_ws c then S (wspan s') else 0%nat
  | [] => 0%nat
  end.

Lemma wspan_le : forall s, (wspan s <= length s)%nat.
Proof. induction s as [|c s IH]; cbn; [lia|]. destruct (is_ws c); lia. Qed.

Lemma wspan_ws : forall s j, (j < wspan s)%nat -> is_ws (nth j s 0) = true.
Proof.
  induction s as [|c s IH]; intros j Hj; cbn in Hj; [lia|].
  destruct (is_ws c) eqn:W; [|lia]. destruct j as [|j]; cbn; [exact W|]. apply IH. lia.
Qed.

Lemma wspan_cons_t : forall c s, is_ws c = true -> wspan (c :: s) = S (wspan s).
Proof. intros c s H. cbn. rewrite H. reflexivity. Qed.
Lemma wspan_cons_f : forall c s, is_ws c = false -> wspan (c :: s) = 0%nat.
Proof. intros c s H. cbn. rewrite H. reflexivity. Qed.

Lemma sows_skipn_at_nth : forall {X} (l : list X) j x, nth_error l j = Some x -> skipn j l = x :: skipn (S j) l.
Proof.
  intros X l. induction l as [|y l IH]; intros [|j] x H; cbn in H |- *; try discriminate.
  - inversion H. reflexivity.
  - apply IH. exact H.
Qed.
Lemma sows_zbytes_skipn : forall j bs, zbytes (skipn j bs) = skipn j (zbytes bs).
Proof. intros j bs. unfold zbytes. rewrite skipn_map. reflexivity. Qed.
Lemma sows_skipn_zbytes_nth : forall bs j b, nth_error bs j = Some b -> skipn j (zbytes bs) = zb b :: skipn (S j) (zbytes bs).
Proof. intros bs j b N. rewrite <- !sows_zbytes_skipn, (sows_skipn_at_nth bs j b N). reflexivity. Qed.
Lemma sows_length_zbytes : forall bs, length (zbytes bs) = length bs.
Proof. intros bs. unfold zbytes. apply length_map. Qed.

