Definition P_B_SKIP_OWS : Z := 0xbd2bc.
Definition SKIP_OWS_STACK : Z := 16.

Definition skip_ows_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (C p La W : Z) (wbs : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) (wz La) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' C [C8 (wz (p + Z.of_nat (wspan (tok_suffix W p wbs))))]
    /\ bytes_at bsegs m' W wbs
    /\ ACONST m'.

Definition skip_ows_stmt : Prop :=
  forall (C p La W : Z) (wbs : list byte) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m C [C8 (wz p)] ->
  bytes_at bsegs m W wbs -> W <= p <= La -> La = W + Z.of_nat (length wbs) -> La < 2^64 ->
  (C + 8 <= W \/ W + Z.of_nat (length wbs) <= C) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + SKIP_OWS_STACK <= bv_unsigned sp -> aceil <= lo ->
  (C + 8 <= lo \/ bv_unsigned sp <= C) ->
  (W + Z.of_nat (length wbs) <= lo \/ bv_unsigned sp <= W) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  C mod 8 = 0 -> accessible m C 8 -> awin (C, C + 8) ->
  (wbs <> [] -> accessible m W (Z.of_nat (length wbs))) -> ACONST m ->
  (* [comment removed for export] *)
  ((0 < length wbs)%nat -> 0 < W) ->
  evt bsegs (skip_ows_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C p La W wbs lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) (wz La) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_SKIP_OWS) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Definition sows_post_c (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (C La W : Z) (wbs : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz C) (wz La) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (C, C + 8)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' C [C8 (wz v)]
    /\ bytes_at bsegs m' W wbs
    /\ ACONST m'.

Lemma skip_ows_post_c : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C p La W wbs lo m,
  skip_ows_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C p La W wbs lo m
  = sows_post_c (p + Z.of_nat (wspan (tok_suffix W p wbs))) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C La W wbs lo m.
Proof. intros. reflexivity. Qed.

