Lemma sows_exit : forall (v : Z) (ra sp : word) (x1 gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m m1 : mem) (C La W : Z) (wbs : list byte) (lo : Z) (j8 : list byte),
  rw_cells bsegs m1 C [C8 (wz v)] -> bytes_at bsegs m1 W wbs ->
  rw_cells bsegs m1 (bv_unsigned sp + -16) [CB 8 j8; C8 ra] ->
  stk bsegs m1 lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp ->
  munch [(lo, bv_unsigned sp); (C, C + 8)]%Z m m1 -> wmono bsegs m m1 -> mem_inv bsegs m1 ->
  Forall awin [(lo, bv_unsigned sp); (C, C + 8)]%Z -> ACONST m ->
  evt bsegs (sows_post_c v ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C La W wbs lo m)
    (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1 (wz C) (wz La) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xbd348) fc None m1 (seg_rom bsegs)).
Proof.
