Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.option Sort Prop.

(* [comment removed for export] *)
Lemma sows_loop : forall (k i : nat) (t1x t2x : word) (ra sp : word)
    (x1 gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m m1 : mem) (C La W : Z) (wbs : list byte) (lo : Z) (j8 : list byte),
  (length wbs - i = k)%nat -> (i < length wbs)%nat ->
  rw_cells bsegs m1 C [C8 (wz (W + Z.of_nat i))] -> bytes_at bsegs m1 W wbs ->
  rw_cells bsegs m1 (bv_unsigned sp + -16) [CB 8 j8; C8 ra] ->
  stk bsegs m1 lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp ->
  munch [(lo, bv_unsigned sp); (C, C + 8)]%Z m m1 -> wmono bsegs m m1 -> mem_inv bsegs m1 ->
  Forall awin [(lo, bv_unsigned sp); (C, C + 8)]%Z -> ACONST m ->
  La = W + Z.of_nat (length wbs) -> La < 2^64 -> (C + 8 <= W \/ W + Z.of_nat (length wbs) <= C) -> 0 < W ->
  (C + 8 <= lo \/ bv_unsigned sp <= C) -> (W + Z.of_nat (length wbs) <= lo \/ bv_unsigned sp <= W) ->
  C mod 8 = 0 -> accessible m C 8 -> accessible m W (Z.of_nat (length wbs)) ->
  evt bsegs (sows_post_c (W + Z.of_nat i + Z.of_nat (wspan (skipn i (zbytes wbs))))
               ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc C La W wbs lo m)
    (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp (wz 9) t1x t2x s0 s1 (wz C) (wz La) (wz (W + Z.of_nat i))
              (wz 2147450880) (wz (Z.shiftr C 3 + 2147450880)) (wz (W + Z.of_nat i)) (wz 32) (wz 1)
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
